/**
 * "Blocked by" links between issues. Every method takes `orgId` first, and blocker rows are always re-read through `issues` under the same tenant predicate, so a link can never surface another organization's issue.
 */
import { and, asc, eq, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { compact } from "./_paging";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { SQL } from "drizzle-orm";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Stores a link, or leaves an identical existing one alone and returns it. */
export async function insertDependency(input: {
  readonly orgId: OrgId;
  readonly issueId: IssueId;
  readonly blockerId: IssueId;
  readonly createdBy: UserId;
}): Promise<IssueDependency> {
  getDb()
    .insert(issueDependencies)
    .values({
      orgId: input.orgId,
      issueId: input.issueId,
      blockerId: input.blockerId,
      createdBy: input.createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();

  const stored = await findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (!stored) {
    throw new Error(
      `Dependency ${input.issueId} <- ${input.blockerId} was not stored`,
    );
  }
  return stored;
}

/** `true` only when a row was actually removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const removed = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ blockerId: issueDependencies.blockerId })
    .all();
  return removed.length > 0;
}

/**
 * Every blocker id of `issueId`, archived or not. The cycle walk needs the
 * whole graph, so archived links still count.
 */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Ids of every issue that `blockerId` is holding back, in this org. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

/** Blockers of `issueId` that are not archived, open or closed, by issue number. */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return blockerIssues(orgId, issueId, [livePredicate(issues.archivedAt, {})]);
}

/** Blockers of `issueId` that still hold it: live and neither done nor canceled. */
export async function listOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return blockerIssues(orgId, issueId, [
    livePredicate(issues.archivedAt, {}),
    notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
  ]);
}

async function blockerIssues(
  orgId: OrgId,
  issueId: IssueId,
  extra: readonly (SQL | undefined)[],
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          ...extra,
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.issue.id as IssueId),
  );
  return rows.map(({ issue }) =>
    toIssue(issue, (labels[issue.id] ?? []).map((label) => label.id)),
  );
}

