import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised by `changeIssueStatus` when an issue with open blockers is marked done. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(
      `Issue cannot be marked done while blocked by ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

/** A self-link or a link that would close a loop. Never stored. */
class BlockerCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly issueId: IssueId, readonly blockerId: IssueId) {
    super(
      `Issue ${issueId} cannot be blocked by ${blockerId}: it would create a dependency cycle`,
    );
    this.name = "BlockerCycleError";
  }
}

type BlockerLink = {
  readonly orgId: OrgId;
  readonly issueId: IssueId;
  readonly blockerId: IssueId;
};

/**
 * Records "`issueId` is blocked by `blockerId`". Adding a link that already
 * exists returns it unchanged. Rejects self-links, links that would close a
 * cycle through any chain, and links touching an archived issue.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));

  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertNotArchived("Issue", blocked.id, blocked);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new BlockerCycleError(input.issueId, input.blockerId);
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  // The new edge closes a loop exactly when the blocker already depends on the
  // blocked issue, directly or through any chain of blockers.
  if (await reachesThroughBlockers(input.orgId, input.blockerId, input.issueId)) {
    throw new BlockerCycleError(input.issueId, input.blockerId);
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
  });
}

/** Deletes one link. Resolves `true` when a link was removed, `false` when none existed. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** Live blockers of `issueId`, open or closed, by issue number ascending. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/**
 * True when `target` is `start`, or when following "blocked by" links from
 * `start` reaches it. Breadth-first over the whole graph, archived links included.
 */
async function reachesThroughBlockers(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([start]);
  const queue: IssueId[] = [start];

  for (let cursor = 0; cursor < queue.length; cursor += 1) {
    const current = queue[cursor];
    if (current === target) return true;

    for (const next of await dependencyRepo.listBlockerIds(orgId, current)) {
      if (seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }

  return false;
}

