/**
 * Unblock notifications. When a blocker closes, the assignee of each issue it was holding back gets one `issue_unblocked` notification, provided nothing else still holds that issue.
 *
 * Must call (do not reimplement): subscribe, isArchived, notify
 */
import { subscribe } from "@/lib/event-bus";
import { isArchived } from "@/lib/soft-delete";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { IssueStatus } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";
import { notify } from "./notification-service";

function isClosed(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * Attaches the unblock reaction to the two events that can close a blocker.
 * Called from `registerEventHandlers()`; the emitting call awaits delivery, so
 * the notification exists by the time the status change or archive returns.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offStatusChanged = subscribe("issue.status_changed", async (payload) => {
    if (isClosed(payload.from) || !isClosed(payload.to)) return;
    await notifyUnblockedBy(payload.orgId, payload.issueId, payload.actorId);
  });

  const offArchived = subscribe("issue.archived", async (payload) => {
    // Archiving does not touch the status, so a blocker that is still open
    // here was open right up until this archive.
    const blocker = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (blocker === null || isClosed(blocker.status)) return;
    await notifyUnblockedBy(payload.orgId, payload.issueId, payload.actorId);
  });

  return () => {
    offStatusChanged();
    offArchived();
  };
}

/**
 * Called once a blocker has just closed. Each issue it blocked is re-checked
 * against the stored state, so only the close that empties the last open
 * blocker produces a notification.
 */
async function notifyUnblockedBy(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const blockedId of await dependencyRepo.listBlockedIssueIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (blocked === null || isArchived(blocked) || isClosed(blocked.status)) {
      continue;
    }
    if (blocked.assigneeId === null) continue;

    const stillOpen = await dependencyRepo.listOpenBlockers(orgId, blocked.id);
    if (stillOpen.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

