import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as depService from "@/server/services/issue-dependency-service";
import { IssueBlockedError } from "@/server/services/issue-dependency-service";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("depsvc");
  other = await createTenant("depother");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

const orgId = () => tenant.org.id;
const member = () => tenant.actors.member;
const admin = () => tenant.actors.admin;

async function makeIssue(title: string, assigneeId: typeof tenant.userIds.member | null = null) {
  return issueService.createIssue(
    member(),
    issueInput(orgId(), tenant.project.id, { title, assigneeId }),
  );
}

async function unblockedFor(issueId: string) {
  const page = await notificationRepo.listNotifications({
    orgId: orgId(),
    recipientId: tenant.userIds.member,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 100,
  } as never);
  return page.items.filter((n) => n.href === `/issues/${issueId}`);
}

describe("link rules", () => {
  it("stores a link once and returns the existing one on duplicate", async () => {
    const a = await makeIssue("A link");
    const b = await makeIssue("B link");
    const first = await depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(first).toMatchObject({ issueId: a.id, blockerId: b.id, createdBy: member().userId });
    const second = await depService.addBlocker(admin(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(second.createdAt).toBe(first.createdAt);
    expect(second.createdBy).toBe(member().userId);
    const list = await depService.listBlockers(member(), orgId(), a.id);
    expect(list.map((i) => i.id)).toEqual([b.id]);
  });

  it("rejects self links and stores nothing", async () => {
    const a = await makeIssue("Self link");
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: a.id })).rejects.toThrow();
    expect(await depService.listBlockers(member(), orgId(), a.id)).toEqual([]);
  });

  it("rejects direct and transitive cycles", async () => {
    const a = await makeIssue("Cyc A");
    const b = await makeIssue("Cyc B");
    const c = await makeIssue("Cyc C");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await depService.addBlocker(member(), { orgId: orgId(), issueId: b.id, blockerId: c.id });
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: c.id, blockerId: a.id })).rejects.toThrow();
    expect(await depService.listBlockers(member(), orgId(), c.id)).toEqual([]);
    expect((await depService.listBlockers(member(), orgId(), b.id)).map((i) => i.id)).toEqual([c.id]);
  });

  it("rejects archived issues on either side", async () => {
    const x = await makeIssue("Arch X");
    const y = await makeIssue("Arch Y");
    await issueService.archiveIssue(admin(), orgId(), y.id);
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: y.id, blockerId: x.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("rejects unknown and other-tenant ids without storing", async () => {
    const x = await makeIssue("NF X");
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: "nope" as never })).rejects.toMatchObject({ code: "not_found" });
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign" }),
    );
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: foreign.id })).rejects.toMatchObject({ code: "not_found" });
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("enforces tenant scope and permission", async () => {
    const x = await makeIssue("Perm X");
    const y = await makeIssue("Perm Y");
    await expect(depService.addBlocker(member(), { orgId: other.org.id, issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(depService.listBlockers(member(), other.org.id, x.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(depService.addBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(depService.removeBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("removeBlocker reports whether a row was removed", async () => {
    const x = await makeIssue("Rm X");
    const y = await makeIssue("Rm Y");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id });
    expect(await depService.removeBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).toBe(true);
    expect(await depService.removeBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).toBe(false);
  });

  it("listBlockers orders by issue number and hides archived blockers", async () => {
    const x = await makeIssue("Ord X");
    const p = await makeIssue("Ord P");
    const q = await makeIssue("Ord Q");
    const r = await makeIssue("Ord R");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: r.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: p.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: q.id });
