});

describe("completion gate", () => {
  it("blocks done while open blockers exist, via changeIssueStatus and moveIssue", async () => {
    const t = await makeIssue("Gate T");
    const b1 = await makeIssue("Gate B1");
    const b2 = await makeIssue("Gate B2");
    const b3 = await makeIssue("Gate B3");
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b3.id, status: "done" });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b1.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b2.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b3.id });

    const seen: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      if (payload.issueId === t.id) seen.push(payload);
    });
    try {
      const err = await issueService
        .changeIssueStatus(admin(), { orgId: orgId(), issueId: t.id, status: "done" })
        .catch((e: unknown) => e);
      expect(err).toBeInstanceOf(IssueBlockedError);
      expect((err as IssueBlockedError).code).toBe("conflict");
      expect((err as IssueBlockedError).blockerIds).toEqual([b1.id, b2.id]);

      const moveErr = await issueService
        .moveIssue(admin(), { orgId: orgId(), issueId: t.id, toStatus: "done", toIndex: 0 })
        .catch((e: unknown) => e);
      expect(moveErr).toBeInstanceOf(IssueBlockedError);
