    const done = await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: t.id, status: "done" });
    expect(done.status).toBe("done");
  });
});

describe("unblock notifications", () => {
  it("notifies the assignee once when the last open blocker is done", async () => {
    const x = await makeIssue("Unb X", tenant.userIds.member);
    const b1 = await makeIssue("Unb B1");
    const b2 = await makeIssue("Unb B2");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b1.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b2.id });

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b1.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(0);

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b2.id, status: "done" });
    const got = await unblockedFor(x.id);
    expect(got).toHaveLength(1);
    expect(got[0]).toMatchObject({ kind: "issue_unblocked", recipientId: tenant.userIds.member, actorId: tenant.userIds.admin });
  });

  it("does not notify on closed to closed, and notifies again after reopen and re-close", async () => {
    const x = await makeIssue("Unb X2", tenant.userIds.member);
