    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "todo" });
    expect(await unblockedFor(x.id)).toHaveLength(1);
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(2);
  });

  it("notifies on archive of an open blocker, not on archive of a closed one", async () => {
    const x = await makeIssue("Unb X3", tenant.userIds.member);
    const openB = await makeIssue("Unb B4");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: openB.id });
    await issueService.archiveIssue(admin(), orgId(), openB.id);
    const got = await unblockedFor(x.id);
    expect(got).toHaveLength(1);
    expect(got[0]).toMatchObject({ actorId: tenant.userIds.admin });

    const y = await makeIssue("Unb X4", tenant.userIds.member);
    const closedB = await makeIssue("Unb B5");
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: closedB.id, status: "done" });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: y.id, blockerId: closedB.id });
    await issueService.archiveIssue(admin(), orgId(), closedB.id);
    expect(await unblockedFor(y.id)).toHaveLength(0);
  });

  it("does not notify the actor about their own action, and removeBlocker never notifies", async () => {
    const x = await makeIssue("Unb X5", tenant.userIds.member);
    const b = await makeIssue("Unb B6");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b.id });
    const solo = await makeIssue("Unb X6", tenant.userIds.member);
    const c = await makeIssue("Unb B7");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: solo.id, blockerId: c.id });

    // Member is both the assignee and the actor here, so no self-notification.
    await issueService.changeIssueStatus(member(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(0);

    await depService.removeBlocker(member(), { orgId: orgId(), issueId: solo.id, blockerId: c.id });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: c.id, status: "done" });
