  });

  it("moveIssue to done also unblocks", async () => {
    const x = await makeIssue("Unb X7", tenant.userIds.member);
    const b = await makeIssue("Unb B8");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b.id });
    await issueService.moveIssue(admin(), { orgId: orgId(), issueId: b.id, toStatus: "done", toIndex: 0 });
    expect(await unblockedFor(x.id)).toHaveLength(1);
  });

  it("skips unassigned or closed blocked issues", async () => {
    const unassigned = await makeIssue("Unb X8");
    const closedX = await makeIssue("Unb X9", tenant.userIds.member);
    const b = await makeIssue("Unb B9");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: unassigned.id, blockerId: b.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: closedX.id, blockerId: b.id });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: closedX.id, status: "canceled" });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(unassigned.id)).toHaveLength(0);
    expect(await unblockedFor(closedX.id)).toHaveLength(0);
  });
});

