import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("depsvc");
  other = await createTenant("depother");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

const orgId = () => tenant.org.id;
const member = () => tenant.actors.member;
const admin = () => tenant.actors.admin;

async function makeIssue(title: string, assigneeId: typeof tenant.userIds.member | null = null) {
  return issueService.createIssue(
    member(),
    issueInput(orgId(), tenant.project.id, { title, assigneeId }),
  );
}

async function unblockedFor(issueId: string) {
  const page = await notificationRepo.listNotifications({
    orgId: orgId(),
    recipientId: tenant.userIds.member,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 100,
  } as never);
  return page.items.filter((n) => n.href === `/issues/${issueId}`);
}

describe("link rules", () => {
  it("stores a link once and returns the existing one on duplicate", async () => {
    const a = await makeIssue("A link");
    const b = await makeIssue("B link");
    const first = await depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(first).toMatchObject({ issueId: a.id, blockerId: b.id, createdBy: member().userId });
    const second = await depService.addBlocker(admin(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(second.createdAt).toBe(first.createdAt);
    expect(second.createdBy).toBe(member().userId);
    const list = await depService.listBlockers(member(), orgId(), a.id);
    expect(list.map((i) => i.id)).toEqual([b.id]);
  });

  it("rejects self links and stores nothing", async () => {
    const a = await makeIssue("Self link");
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: a.id })).rejects.toThrow();
    expect(await depService.listBlockers(member(), orgId(), a.id)).toEqual([]);
  });

  it("rejects direct and transitive cycles", async () => {
    const a = await makeIssue("Cyc A");
    const b = await makeIssue("Cyc B");
    const c = await makeIssue("Cyc C");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: a.id, blockerId: b.id });
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await depService.addBlocker(member(), { orgId: orgId(), issueId: b.id, blockerId: c.id });
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: c.id, blockerId: a.id })).rejects.toThrow();
    expect(await depService.listBlockers(member(), orgId(), c.id)).toEqual([]);
    expect((await depService.listBlockers(member(), orgId(), b.id)).map((i) => i.id)).toEqual([c.id]);
  });

  it("rejects archived issues on either side", async () => {
    const x = await makeIssue("Arch X");
    const y = await makeIssue("Arch Y");
    await issueService.archiveIssue(admin(), orgId(), y.id);
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: y.id, blockerId: x.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("rejects unknown and other-tenant ids without storing", async () => {
    const x = await makeIssue("NF X");
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: "nope" as never })).rejects.toMatchObject({ code: "not_found" });
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign" }),
    );
    await expect(depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: foreign.id })).rejects.toMatchObject({ code: "not_found" });
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("enforces tenant scope and permission", async () => {
    const x = await makeIssue("Perm X");
    const y = await makeIssue("Perm Y");
    await expect(depService.addBlocker(member(), { orgId: other.org.id, issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(depService.listBlockers(member(), other.org.id, x.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(depService.addBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(depService.removeBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: x.id, blockerId: y.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await depService.listBlockers(member(), orgId(), x.id)).toEqual([]);
  });

  it("removeBlocker reports whether a row was removed", async () => {
    const x = await makeIssue("Rm X");
    const y = await makeIssue("Rm Y");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id });
    expect(await depService.removeBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).toBe(true);
    expect(await depService.removeBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: y.id })).toBe(false);
  });

  it("listBlockers orders by issue number and hides archived blockers", async () => {
    const x = await makeIssue("Ord X");
    const p = await makeIssue("Ord P");
    const q = await makeIssue("Ord Q");
    const r = await makeIssue("Ord R");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: r.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: p.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: q.id });
    expect((await depService.listBlockers(member(), orgId(), x.id)).map((i) => i.id)).toEqual([p.id, q.id, r.id]);
    await issueService.archiveIssue(admin(), orgId(), q.id);
    expect((await depService.listBlockers(member(), orgId(), x.id)).map((i) => i.id)).toEqual([p.id, r.id]);
  });
});

describe("completion gate", () => {
  it("blocks done while open blockers exist, via changeIssueStatus and moveIssue", async () => {
    const t = await makeIssue("Gate T");
    const b1 = await makeIssue("Gate B1");
    const b2 = await makeIssue("Gate B2");
    const b3 = await makeIssue("Gate B3");
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b3.id, status: "done" });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b1.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b2.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b3.id });

    const seen: unknown[] = [];
    const off = subscribe("issue.status_changed", (payload) => {
      if (payload.issueId === t.id) seen.push(payload);
    });
    try {
      const err = await issueService
        .changeIssueStatus(admin(), { orgId: orgId(), issueId: t.id, status: "done" })
        .catch((e: unknown) => e);
      expect(err).toBeInstanceOf(IssueBlockedError);
      expect((err as IssueBlockedError).code).toBe("conflict");
      expect((err as IssueBlockedError).blockerIds).toEqual([b1.id, b2.id]);

      const moveErr = await issueService
        .moveIssue(admin(), { orgId: orgId(), issueId: t.id, toStatus: "done", toIndex: 0 })
        .catch((e: unknown) => e);
      expect(moveErr).toBeInstanceOf(IssueBlockedError);
      expect(seen).toHaveLength(0);
      const stored = await issueRepo.findIssueById(orgId(), t.id);
      expect(stored?.status).toBe("backlog");
    } finally {
      off();
    }

    const canceled = await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: t.id, status: "canceled" });
    expect(canceled.status).toBe("canceled");
  });

  it("allows done once every blocker is closed", async () => {
    const t = await makeIssue("Gate T2");
    const b = await makeIssue("Gate B4");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: t.id, blockerId: b.id });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "canceled" });
    const done = await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: t.id, status: "done" });
    expect(done.status).toBe("done");
  });
});

describe("unblock notifications", () => {
  it("notifies the assignee once when the last open blocker is done", async () => {
    const x = await makeIssue("Unb X", tenant.userIds.member);
    const b1 = await makeIssue("Unb B1");
    const b2 = await makeIssue("Unb B2");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b1.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b2.id });

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b1.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(0);

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b2.id, status: "done" });
    const got = await unblockedFor(x.id);
    expect(got).toHaveLength(1);
    expect(got[0]).toMatchObject({ kind: "issue_unblocked", recipientId: tenant.userIds.member, actorId: tenant.userIds.admin });
  });

  it("does not notify on closed to closed, and notifies again after reopen and re-close", async () => {
    const x = await makeIssue("Unb X2", tenant.userIds.member);
    const b = await makeIssue("Unb B3");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b.id });

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(1);
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "canceled" });
    expect(await unblockedFor(x.id)).toHaveLength(1);

    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "todo" });
    expect(await unblockedFor(x.id)).toHaveLength(1);
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(2);
  });

  it("notifies on archive of an open blocker, not on archive of a closed one", async () => {
    const x = await makeIssue("Unb X3", tenant.userIds.member);
    const openB = await makeIssue("Unb B4");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: openB.id });
    await issueService.archiveIssue(admin(), orgId(), openB.id);
    const got = await unblockedFor(x.id);
    expect(got).toHaveLength(1);
    expect(got[0]).toMatchObject({ actorId: tenant.userIds.admin });

    const y = await makeIssue("Unb X4", tenant.userIds.member);
    const closedB = await makeIssue("Unb B5");
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: closedB.id, status: "done" });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: y.id, blockerId: closedB.id });
    await issueService.archiveIssue(admin(), orgId(), closedB.id);
    expect(await unblockedFor(y.id)).toHaveLength(0);
  });

  it("does not notify the actor about their own action, and removeBlocker never notifies", async () => {
    const x = await makeIssue("Unb X5", tenant.userIds.member);
    const b = await makeIssue("Unb B6");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b.id });
    const solo = await makeIssue("Unb X6", tenant.userIds.member);
    const c = await makeIssue("Unb B7");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: solo.id, blockerId: c.id });

    // Member is both the assignee and the actor here, so no self-notification.
    await issueService.changeIssueStatus(member(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(x.id)).toHaveLength(0);

    await depService.removeBlocker(member(), { orgId: orgId(), issueId: solo.id, blockerId: c.id });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: c.id, status: "done" });
    expect(await unblockedFor(solo.id)).toHaveLength(0);
  });

  it("moveIssue to done also unblocks", async () => {
    const x = await makeIssue("Unb X7", tenant.userIds.member);
    const b = await makeIssue("Unb B8");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: x.id, blockerId: b.id });
    await issueService.moveIssue(admin(), { orgId: orgId(), issueId: b.id, toStatus: "done", toIndex: 0 });
    expect(await unblockedFor(x.id)).toHaveLength(1);
  });

  it("skips unassigned or closed blocked issues", async () => {
    const unassigned = await makeIssue("Unb X8");
    const closedX = await makeIssue("Unb X9", tenant.userIds.member);
    const b = await makeIssue("Unb B9");
    await depService.addBlocker(member(), { orgId: orgId(), issueId: unassigned.id, blockerId: b.id });
    await depService.addBlocker(member(), { orgId: orgId(), issueId: closedX.id, blockerId: b.id });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: closedX.id, status: "canceled" });
    await issueService.changeIssueStatus(admin(), { orgId: orgId(), issueId: b.id, status: "done" });
    expect(await unblockedFor(unassigned.id)).toHaveLength(0);
    expect(await unblockedFor(closedX.id)).toHaveLength(0);
  });
});

